# Meeus, Astronomical Algorithms ch. 47 (truncated). Returns geocentric ecliptic J2000 x,y,z in km.
LR=[(0,0,1,0,6288774,-20905355),(2,0,-1,0,1274027,-3699111),(2,0,0,0,658314,-2955968),(0,0,2,0,213618,-569925),(0,1,0,0,-185116,48888),(0,0,0,2,-114332,-3149),(2,0,-2,0,58793,246158),(2,-1,-1,0,57066,-152138),(2,0,1,0,53322,-170733),(2,-1,0,0,45758,-204586),(0,1,-1,0,-40923,-129620),(1,0,0,0,-34720,108743),(0,1,1,0,-30383,104755),(2,0,0,-2,15327,10321),(0,0,1,2,-12528,0),(0,0,1,-2,10980,79661),(4,0,-1,0,10675,-34782),(0,0,3,0,10034,-23210),(4,0,-2,0,8548,-21636),(2,1,-1,0,-7888,24208),(2,1,0,0,-6766,30824),(1,0,-1,0,-5163,-8379),(1,1,0,0,4987,-16675),(2,-1,1,0,4036,-12831),(2,0,2,0,3994,-10445),(4,0,0,0,3861,-11650),(2,0,-3,0,3665,14403),(0,1,-2,0,-2689,-7003),(2,0,-1,2,-2602,0),(2,-1,-2,0,2390,10056),(1,0,1,0,-2348,6322),(2,-2,0,0,2236,-9884),(0,1,2,0,-2120,5751),(0,2,0,0,-2069,0),(2,-2,-1,0,2048,-4950),(2,0,1,-2,-1773,4130),(2,0,0,2,-1595,0),(4,-1,-1,0,1215,-3958),(0,0,2,2,-1110,0),(3,0,-1,0,-892,3258),(2,1,1,0,-810,2616),(4,-1,-2,0,759,-1897),(0,2,-1,0,-713,-2117),(2,2,-1,0,-700,2354),(2,1,-2,0,691,0),(2,-1,0,-2,596,0),(4,0,1,0,549,-1423),(0,0,4,0,537,-1117),(4,-1,0,0,520,-1571),(1,0,-2,0,-487,-1739),(2,1,0,-2,-399,0),(0,0,2,-2,-381,-4421),(1,1,1,0,351,0),(3,0,-2,0,-340,0),(4,0,-3,0,330,0),(2,-1,2,0,327,0),(0,2,1,0,-323,1165),(1,1,-1,0,299,0),(2,0,3,0,294,0),(2,0,-1,-2,0,8752)]
B=[(0,0,0,1,5128122),(0,0,1,1,280602),(0,0,1,-1,277693),(2,0,0,-1,173237),(2,0,-1,1,55413),(2,0,-1,-1,46271),(2,0,0,1,32573),(0,0,2,1,17198),(2,0,1,-1,9266),(0,0,2,-1,8822),(2,-1,0,-1,8216),(2,0,-2,-1,4324),(2,0,1,1,4200),(2,1,0,-1,-3359),(2,-1,-1,1,2463),(2,-1,0,1,2211),(2,-1,-1,-1,2065),(0,1,-1,-1,-1870),(4,0,-1,-1,1828),(0,1,0,1,-1794),(0,0,0,3,-1749),(0,1,-1,1,-1565),(1,0,0,1,-1491),(0,1,1,1,-1475),(0,1,1,-1,-1410),(0,1,0,-1,-1344),(1,0,0,-1,-1335),(0,0,3,1,1107),(4,0,0,-1,1021),(4,0,-1,1,833),(0,0,1,-3,777),(4,0,-2,1,671),(2,0,0,-3,607),(2,0,2,-1,596),(2,-1,1,-1,491),(2,0,-2,1,-451),(0,0,3,-1,439),(2,0,2,1,422),(2,0,-3,-1,421),(2,1,-1,1,-366),(2,1,0,1,-351),(4,0,0,1,331),(2,-1,1,1,315),(2,-2,0,-1,302),(0,0,1,3,-283),(2,1,1,-1,-229),(1,1,0,-1,223),(1,1,0,1,223),(0,1,-2,-1,-220),(2,1,-1,-1,-220),(1,0,1,1,-185),(2,-1,-2,-1,181),(0,1,2,1,-177),(4,0,-2,-1,176),(4,-1,-1,-1,166),(1,0,1,-1,-164),(4,0,1,-1,132),(1,0,-1,-1,-119),(4,-1,0,-1,115),(2,-2,0,1,107)]
def moon_j2000_km(jd):
    T=(jd-2451545.0)/36525.0
    d=math.radians
    Lp=218.3164477+481267.88123421*T-0.0015786*T*T+T**3/538841-T**4/65194000
    D=297.8501921+445267.1114034*T-0.0018819*T*T+T**3/545868-T**4/113065000
    M=357.5291092+35999.0502909*T-0.0001536*T*T+T**3/24490000
    Mp=134.9633964+477198.8675055*T+0.0087414*T*T+T**3/69699-T**4/14712000
    F=93.2720950+483202.0175233*T-0.0036539*T*T-T**3/3526000+T**4/863310000
    A1=119.75+131.849*T; A2=53.09+479264.290*T; A3=313.45+481266.484*T
    E=1-0.002516*T-0.0000074*T*T
    sl=sr=sb=0.0
    for (cd,cm,cmp,cf,l,r) in LR:
        arg=d(cd*D+cm*M+cmp*Mp+cf*F); ef=E**abs(cm)
        sl+=l*ef*math.sin(arg); sr+=r*ef*math.cos(arg)
    for (cd,cm,cmp,cf,b) in B:
        arg=d(cd*D+cm*M+cmp*Mp+cf*F); ef=E**abs(cm)
        sb+=b*ef*math.sin(arg)
    sl+=3958*math.sin(d(A1))+1962*math.sin(d(Lp-F))+318*math.sin(d(A2))
    sb+=-2235*math.sin(d(Lp))+382*math.sin(d(A3))+175*math.sin(d(A1-F))+175*math.sin(d(A1+F))+127*math.sin(d(Lp-Mp))-115*math.sin(d(Lp+Mp))
    lam=Lp+sl/1e6; beta=sb/1e6; dist=385000.56+sr/1000
    # mean equinox of date -> J2000: remove general precession in longitude
    lam-=1.3969713*T
    lam=d(lam); beta=d(beta)
    return (dist*math.cos(beta)*math.cos(lam), dist*math.cos(beta)*math.sin(lam), dist*math.sin(beta))
